<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed,nextTick} from 'vue';
import {Plus,KeyRound,Check,FlaskConical,X,Link2} from 'lucide-vue-next';
import {invoke} from '../bridge';
import {useDesktop} from '../useDesktop';
import {trapModalFocus} from '../modalFocus';
import type {Instance,ConnectionProfile,ConnectionKind,ConnectionSnapshot} from '../../types';
const props=defineProps<{instance?:Instance}>();const d=useDesktop();
const snapshot=ref<ConnectionSnapshot>({profiles:[],bindings:{},readOnly:false}),error=ref(''),pending=ref(''),editor=ref(false),generation=ref<ConnectionProfile|null>(null),paid=ref(false),dialog=ref<HTMLElement|null>(null);
const kind=ref<ConnectionKind>('decision'),selection=ref('');
const serviceName=(kind:ConnectionKind)=>kind==='decision'?'决策主持':kind==='knowledge'?'知识顾问 · Gemini':'服务端声音';
function changeKind(){if(form.value.kind==='knowledge'){form.value.baseURL='https://generativelanguage.googleapis.com/v1beta';form.value.jsonMode=false;}else if(form.value.baseURL==='https://generativelanguage.googleapis.com/v1beta')form.value.baseURL='';}
const fresh=()=>({id:undefined as string|undefined,revision:undefined as number|undefined,name:'',kind:'decision' as ConnectionKind,baseURL:'',model:'',voice:'alloy',jsonMode:false,keyAction:'replace',key:''});const form=ref(fresh());
const profileOptions=computed(()=>snapshot.value.profiles.filter(p=>p.kind===kind.value));
const bindings=computed(()=>props.instance?snapshot.value.bindings[props.instance.id]||{}:{});
const editModels=computed(()=>snapshot.value.profiles.find(p=>p.id===form.value.id)?.test?.models||[]);
let disposed=false;let releaseFocus:(()=>void)|undefined;
async function load(){try{const value=await invoke<ConnectionSnapshot>('connections');if(!disposed)snapshot.value=value;}catch(e:any){if(!disposed)error.value=e.message;}}
async function operation(key:string,action:()=>Promise<void>){if(pending.value)return;pending.value=key;error.value='';try{await action();}catch(e:any){error.value=e.message;}finally{pending.value='';}}
async function focusModal(){await nextTick();if(dialog.value)releaseFocus=trapModalFocus(dialog.value,()=>{if(!pending.value)close();});}
function close(){releaseFocus?.();releaseFocus=undefined;editor.value=false;generation.value=null;paid.value=false;form.value=fresh();}
function edit(profile?:ConnectionProfile){if(editor.value||generation.value)return;form.value=profile?{...profile,key:'',keyAction:'keep'}:fresh();editor.value=true;void focusModal();}
function save(){void operation('save',async()=>{snapshot.value=await invoke('saveConnectionProfile',form.value);close();d.flash('连接档案已加密保存。已有酒馆保持原应用版本，需明确应用更新。');});}
function remove(profile:ConnectionProfile){if(!confirm('删除连接档案“'+profile.name+'”？已应用到酒馆的档案需先解除关联。'))return;void operation(profile.id,async()=>{snapshot.value=await invoke('removeConnectionProfile',{profileId:profile.id});});}
function models(profile:ConnectionProfile){void operation(profile.id,async()=>{await invoke('testConnectionProfile',{profileId:profile.id,mode:'models'});await load();});}
function preview(profile:ConnectionProfile){if(editor.value||generation.value)return;generation.value=profile;paid.value=false;void focusModal();}
function generate(){const profile=generation.value;if(!profile||!paid.value)return;void operation(profile.id,async()=>{await invoke('testConnectionProfile',{profileId:profile.id,mode:'generate',paidConfirmed:true});await load();close();});}
function apply(){if(!props.instance)return;const target=props.instance;void operation('bind',async()=>{const value=await invoke('bindConnectionProfile',{instanceId:target.id,kind:kind.value,profileId:selection.value||null,restart:target.status==='running'});if(value.cancelled)return;snapshot.value=value;await d.refresh();if(d.selected.value===target.id)d.settings.value=await invoke('settings',{instanceId:target.id});d.flash(target.status==='running'?'档案已应用，正在重新启动酒馆。请在任务中心确认健康检查结果。':'档案已应用，下次启动生效。房间模型模式保持原设置。');});}
onMounted(load);onUnmounted(()=>{disposed=true;releaseFocus?.();form.value=fresh();});
</script>
<template>
 <section class="panel connections-panel"><div class="panel-title"><h3><KeyRound :size="18"/>连接档案</h3><button class="secondary" :disabled="snapshot.readOnly||!!pending" @click="edit()"><Plus :size="16"/>添加连接</button></div>
  <p class="help-text">决策模型、可选知识顾问与声音使用独立档案，密钥通过系统加密保存在本机。编辑档案不会自动改动已应用的酒馆；房间是否使用真实主持仍在冒险桌中决定。</p>
  <p v-if="snapshot.error||error" class="warning" role="alert">{{snapshot.error||error}}</p>
  <div v-if="instance" class="connection-binding"><h4><Link2 :size="16"/>应用到 {{instance.name}}</h4><div class="form form-grid"><label>服务用途<select aria-label="服务用途" v-model="kind" :disabled="!!pending" @change="selection=''"><option value="decision">决策主持</option><option value="tts">服务端声音</option><option value="knowledge">知识顾问 · Gemini（可选）</option></select></label><label>连接档案<select aria-label="应用的连接档案" v-model="selection" :disabled="snapshot.readOnly||!!pending"><option value="">解除此用途的档案，恢复原配置</option><option v-for="p in profileOptions" :key="p.id" :value="p.id">{{p.name}} · {{p.model}} · r{{p.revision}}</option></select></label></div>
   <p v-for="(binding,service) in bindings" :key="service" class="help-text">{{serviceName(service)}}：{{snapshot.profiles.find(p=>p.id===binding?.profileId)?.name||'保留的档案'}} · 已应用 r{{binding?.revision}} <span v-if="snapshot.profiles.find(p=>p.id===binding?.profileId)?.revision!==binding?.revision" class="badge">档案已有新修订，尚未应用</span></p>
   <p class="help-text">{{instance.status==='running'?'应用时将先停止服务，同伴会暂时断线，再重新启动。任务进行中不能更改。':'只注入运行环境，原 settings.json 不会被覆盖。解除后恢复该用途的原配置。'}}</p><button class="secondary" :disabled="snapshot.readOnly||!!pending||instance.status==='busy'" @click="apply">{{pending==='bind'?'正在应用…':instance.status==='running'?'应用并重启酒馆':'应用到此酒馆'}}</button>
  </div>
  <div v-if="!snapshot.profiles.length" class="connection-empty"><KeyRound :size="24"/><p>演示模式不需要密钥。准备使用真实模型时，添加一个决策连接即可。</p></div>
  <article v-for="profile in snapshot.profiles" :key="profile.id" class="connection-card"><div class="panel-title"><h4>{{profile.name}} <small>{{serviceName(profile.kind)}} · r{{profile.revision}}</small></h4><span class="badge">{{profile.keyConfigured?'密钥已保存':'未配置密钥'}}</span></div><p>{{profile.model}}</p><code>{{profile.baseURL}}</code><p v-if="profile.test" :class="profile.test.status==='failed'?'warning':'help-text'" role="status">{{profile.test.mode==='models'?'模型列表检测':'实际生成测试'}} · {{profile.test.detail}}</p><p v-else class="help-text">尚未检测。保存档案不代表接口、余额或实际生成可用。</p><div class="row"><button class="text-button" :disabled="snapshot.readOnly||!!pending" @click="edit(profile)">编辑</button><button class="text-button" :disabled="snapshot.readOnly||!!pending||!profile.keyConfigured" @click="models(profile)">获取模型列表</button><button class="text-button" :disabled="snapshot.readOnly||!!pending||!profile.keyConfigured" @click="preview(profile)"><FlaskConical :size="15"/>实际生成测试</button><button class="text-button danger" :disabled="snapshot.readOnly||!!pending" @click="remove(profile)">删除</button></div></article>
 </section>
 <Teleport to="body"><div v-if="editor||generation" class="overlay"><section ref="dialog" class="dialog connection-editor" role="dialog" aria-modal="true" :aria-label="editor?'连接档案编辑':'实际生成测试确认'"><button class="dialog-close" aria-label="关闭连接弹窗" :disabled="!!pending" @click="close"><X :size="20"/></button>
  <template v-if="editor"><span class="eyebrow">SERVICE CONNECTION</span><h2>{{form.id?'编辑连接':'添加连接'}}</h2><form class="form" @submit.prevent="save"><div class="form-grid"><label>档案名称<input v-model="form.name" maxlength="60" required :disabled="!!pending"/></label><label>用途<select aria-label="用途" v-model="form.kind" :disabled="!!form.id||!!pending" @change="changeKind"><option value="decision">决策主持</option><option value="tts">服务端声音</option><option value="knowledge">知识顾问 · Gemini（可选）</option></select></label></div><label>API 基础地址<input v-model="form.baseURL" type="url" placeholder="https://api.example.com/v1" maxlength="512" required :disabled="!!pending||form.kind==='knowledge'"/></label><label>模型标识<input v-model="form.model" maxlength="160" required :disabled="!!pending" :list="editModels.length?'connection-models':undefined" placeholder="填写供应商的准确模型 ID"/><datalist id="connection-models"><option v-for="model in editModels" :key="model" :value="model"/></datalist></label><label v-if="form.kind==='tts'">声音 ID<input v-model="form.voice" maxlength="160" :disabled="!!pending"/></label><label v-else-if="form.kind==='decision'" class="checkbox"><input v-model="form.jsonMode" type="checkbox" :disabled="!!pending"/>请求 JSON 对象模式（仅供应商支持时启用）</label><label>密钥处理<select v-model="form.keyAction" :disabled="!!pending"><option v-if="form.id" value="keep">保留已保存密钥</option><option value="replace">{{form.id?'替换密钥':'填写密钥'}}</option><option value="clear">清除密钥</option></select></label><label v-if="form.keyAction==='replace'">新 API Key<input v-model="form.key" type="password" maxlength="2048" autocomplete="new-password" required :disabled="!!pending"/></label><p v-if="form.kind==='knowledge'" class="help-text">高级双模型模式使用；单模型无需知识顾问。接口与现有宿主一致，固定 Gemini 官方地址。模型填写 ID，不含 models/ 前缀；应用不会自动切换房间模式。</p><p class="help-text">密钥不回显，也不写入浏览器持久存储。保存不发送生成请求；模型列表检测和可能收费的生成测试均需单独点击。</p><p v-if="error" class="warning" role="alert">{{error}}</p><button class="primary" :disabled="!!pending"><Check :size="16"/>{{pending==='save'?'保存中…':'加密保存档案'}}</button></form></template>
  <template v-else-if="generation"><span class="eyebrow">EXPLICIT TEST</span><h2>发送一次生成测试</h2><p>使用 {{generation.name}} 的 {{generation.model}}。供应商可能收费，不会读取房间、角色、世界书或私有测试文件。</p><div class="test-request"><b>请求预览</b><p>{{generation.kind!=='tts'?'文本：只回复 OK，不生成故事。最多请求 16 个输出 token。':'声音：你好。声音 ID '+(generation.voice||'alloy')+'，请求 MP3。'}}</p><code>{{generation.baseURL}}{{generation.kind==='knowledge'?'/models/'+generation.model+':generateContent':generation.kind==='decision'?'/chat/completions':'/audio/speech'}}</code></div><label class="checkbox"><input v-model="paid" type="checkbox" :disabled="!!pending"/>我同意发送一次可能收费的测试请求</label><p v-if="error" class="warning" role="alert">{{error}}</p><div class="row"><button class="secondary" :disabled="!!pending" @click="close">取消</button><button class="primary" :disabled="!paid||!!pending" @click="generate">{{pending?'检测中…':'发送一次测试（可能收费）'}}</button></div></template>
 </section></div></Teleport>
</template>
